#!/usr/bin/env node
// make-birthday-song.js - "Happy Birthday" arranged for the SID, FROM CODE.
//
// Same approach as tools/make-default-song.js: the song is composed
// deterministically (no randomness - identical bytes every run) and written
// through gt2-sng-writer.js, so it comes into the tracker through exactly the
// same verified parser as any user import.
//
// The melody is the traditional "Good Morning to All" tune (public domain);
// the ARRANGEMENT here - the waltz bass, the arpeggio stabs, the drum kit,
// the PWM and filter settings - is generated by this file.
//
// Musical shape: 3/4 waltz, 12 rows per bar (4 rows = one beat = a quarter
// note), C major. One bar of intro sets the oom-pah-pah going and carries the
// two-eighth "Hap-py" pickup, then the eight-bar tune, then the whole thing
// again a fourth higher - the key change every birthday singalong reaches for.
//
// Usage: node tools/make-birthday-song.js [out.sng]   (default sids/happy-birthday.sng)
import { writeSng } from '../gt2-sng-writer.js';
import { generateArpeggio, generatePWM, generateFilterSweep, generateVibrato,
         generateDrum, generateSustain, WAVEFORMS } from '../table-generators.js';
import { writeFileSync } from 'node:fs';

// ---------------------------------------------------------------- note helpers
// GT2 note byte: 0x60 + (octave-1)*12 + semitone   (C-4 = 0x84)
const N = { C: 0, Cs: 1, D: 2, Ds: 3, E: 4, F: 5, Fs: 6, G: 7, Gs: 8, A: 9, As: 10, B: 11 };
const note = (name, oct) => 0x60 + (oct - 1) * 12 + N[name];
const KEYOFF = 0xBE, EMPTY = 0;

const row = (note = EMPTY, instrument = 0, command = 0, cmdData = 0) =>
    ({ note, instrument, command, cmdData });

function pattern(len, fill) {
    const data = Array.from({ length: len }, () => row());
    if (fill) fill(data);
    return { length: len, data };
}

// ---------------------------------------------------------------- tables
const L = [[], [], [], []], R = [[], [], [], []];
const WTBL = 0, PTBL = 1, FTBL = 2, STBL = 3;
function push(t, l, r) { L[t].push(l & 0xFF); R[t].push(r & 0xFF); return L[t].length; }
const here = (t) => L[t].length + 1;   // 1-based pointer of the NEXT entry
const at = (t) => L[t].length;         // 0-based index of the next entry

// Byte-level table layout comes from ../table-generators.js - the same pure
// module the browser table editor uses, so the traps (delay = value+1 frames,
// absolute 1-based jump targets, routing in the FTBL right byte, drums need
// absolute notes) live in one place.
function emit(t, result) {
    const start = here(t);
    result.entries.forEach(e => push(t, e.left, e.right));
    return start;
}

const PULSE = WAVEFORMS.pulse, NOISE = WAVEFORMS.noise;

// --- WTBL: chord arpeggios, one frame per chord tone (the C64 "chord from a
// single voice"). Major for C and F, dominant 7th for the G bars.
const arp = (chord) =>
    emit(WTBL, generateArpeggio({ chord, waveform: PULSE, stepFrames: 1, startPos: at(WTBL) }));
const ARP_MAJ  = arp([0, 4, 7]);
const ARP_DOM7 = arp([0, 4, 7, 10]);

// --- WTBL: the plain sustained table every pitched instrument needs. Without
// it gplay.c never writes the note frequency at all (WAVEEXEC is skipped when
// the instrument has no wavetable), so the song is silent on real hardware and
// in the exported .SID while sounding fine in a permissive engine.
const WT_SUSTAIN = emit(WTBL, generateSustain({ waveform: PULSE, startPos: at(WTBL) }));

// --- WTBL: drum onsets. Absolute notes, so they survive the order-list
// transpose of the second pass.
const WT_KICK  = emit(WTBL, generateDrum({ kind: 'kick' }));
const WT_SNARE = emit(WTBL, generateDrum({ kind: 'snare' }));
const WT_HAT   = emit(WTBL, generateDrum({ kind: 'hat' }));

// --- PTBL: pulse-width sweeps. The lead sits wide and singing, the bass
// narrow and buzzy so it stays audible under the melody.
//
// KEEP EVERY PULSE VALUE EVEN: depth/rate must divide to an EVEN integer step,
// and center - depth/2 must be even. GT2's two playroutines disagree about the
// bottom bit of the pulse-width low byte - gplay.c (the editor, and our
// reference) writes `cptr->pulse & 0xfe`, while player.s (the 6502 driver the
// .SID exporter embeds) writes the byte raw. An odd pulse value therefore
// makes the exported .SID differ from the reference by 1 LSB on $02/$09/$10
// for as long as the sweep runs. It is inaudible - 1 part in 4096 of the pulse
// width - but it is a real register difference, and keeping the arithmetic
// even costs nothing and keeps `make verify` honest for the whole corpus.
const PW_LEAD = emit(PTBL, generatePWM({ center: 0x7A0, depth: 320, rate: 40, startPos: at(PTBL) }));
const PW_BASS = emit(PTBL, generatePWM({ center: 0x240, depth: 144, rate: 36, startPos: at(PTBL) }));
const PW_STAB = emit(PTBL, generatePWM({ center: 0x400, depth: 240, rate: 24, startPos: at(PTBL) }));

// --- FTBL: one gentle global low-pass sweep. Routing 0b011 = voices 1+2 only,
// so the drums stay dry.
const FILTER_SWEEP = emit(FTBL, generateFilterSweep({
    mode: 'lowpass', resonance: 8, routing: 0b011,
    low: 0x50, high: 0xD0, rate: 64, startPos: at(FTBL),
}));

// --- STBL: vibrato for the lead (a parameter slot, not a program)
const VIB_LEAD = emit(STBL, generateVibrato({ periodFrames: 10, depth: 80 }));
const VIB_NONE = 0;

// ---------------------------------------------------------------- instruments
// INSTRUMENT 1 MUST NOT HAVE VIBRATO. GT2's 6502 player initialises every
// channel to instrument 1, so a never-gated channel carrying a vibrato
// instrument wiggles its (inaudible) frequency register - a player-vs-editor
// quirk that shows up as a register diff against gplay.c. The lead rests
// through the intro bar, so it hits exactly that case; the bass leads instead.
const instruments = [
    { name: 'Waltz Bass', ad: 0x08, sr: 0x59, firstWave: PULSE, gateTimer: 0x02,
      tables: { wave: WT_SUSTAIN, pulse: PW_BASS, filter: 0, speed: VIB_NONE } },
    { name: 'Song Lead',  ad: 0x07, sr: 0x6A, firstWave: PULSE, gateTimer: 0x02,
      tables: { wave: WT_SUSTAIN, pulse: PW_LEAD, filter: 0, speed: VIB_LEAD }, vibratoDelay: 12 },
    { name: 'Chord Stab', ad: 0x05, sr: 0x49, firstWave: PULSE, gateTimer: 0x02,
      tables: { wave: ARP_MAJ, pulse: PW_STAB, filter: 0, speed: VIB_NONE } },
    { name: 'Kick',       ad: 0x00, sr: 0x88, firstWave: NOISE, gateTimer: 0x02,
      tables: { wave: WT_KICK, pulse: 0, filter: 0, speed: VIB_NONE } },
    { name: 'Snare',      ad: 0x00, sr: 0x9A, firstWave: NOISE, gateTimer: 0x02,
      tables: { wave: WT_SNARE, pulse: 0, filter: 0, speed: VIB_NONE } },
    { name: 'Hat',        ad: 0x00, sr: 0x56, firstWave: NOISE, gateTimer: 0x02,
      tables: { wave: WT_HAT, pulse: 0, filter: 0, speed: VIB_NONE } },
];
const I_BASS = 1, I_LEAD = 2, I_ARP = 3, I_KICK = 4, I_SNARE = 5, I_HAT = 6;

// ---------------------------------------------------------------- song
const ROWS = 12;      // 3/4: three beats of four sixteenth-note rows
const BEAT = 4;
const SPEED = 6;      // 6 frames/row -> quarter = 0.48 s ~ 125 BPM waltz
const BARS = 9;       // 1 intro bar + the 8-bar tune

// The melody, as absolute [row, name, octave, lengthRows] with row 0 = the
// start of the intro bar. The two-eighth "Hap-py" pickups land in the last
// beat of the PRECEDING bar, which is why this is written as one flat list and
// sliced into bars afterwards rather than bar by bar.
const MELODY = [
    [ 8, 'G', 4, 2], [10, 'G', 4, 2],                    // pickup: "Hap-py"
    [12, 'A', 4, 4], [16, 'G', 4, 4], [20, 'C', 5, 4],   // "birth-day to"
    [24, 'B', 4, 8], [32, 'G', 4, 2], [34, 'G', 4, 2],   // "you"      + pickup
    [36, 'A', 4, 4], [40, 'G', 4, 4], [44, 'D', 5, 4],
    [48, 'C', 5, 8], [56, 'G', 4, 2], [58, 'G', 4, 2],
    [60, 'G', 5, 4], [64, 'E', 5, 4], [68, 'C', 5, 4],   // "birth-day dear"
    [72, 'B', 4, 4], [76, 'A', 4, 4], [80, 'F', 5, 2], [82, 'F', 5, 2],
    [84, 'E', 5, 4], [88, 'C', 5, 4], [92, 'D', 5, 4],
    [96, 'C', 5, 12],                                    // the final "you"
];

// Harmony, one entry per bar: chord root and which arp table voices it.
const CHORDS = [
    { root: 'C', oct: 2, arp: ARP_MAJ  },   // bar 0 - intro
    { root: 'C', oct: 2, arp: ARP_MAJ  },
    { root: 'G', oct: 2, arp: ARP_DOM7 },
    { root: 'G', oct: 2, arp: ARP_DOM7 },
    { root: 'C', oct: 2, arp: ARP_MAJ  },
    { root: 'C', oct: 2, arp: ARP_MAJ  },
    { root: 'G', oct: 2, arp: ARP_DOM7 },
    { root: 'F', oct: 2, arp: ARP_MAJ  },
    { root: 'C', oct: 2, arp: ARP_MAJ  },
];

const patterns = [];
const P = (p) => (patterns.push(p), patterns.length - 1);

// --- voice 0: the melody. One pattern per bar, filled from the flat MELODY.
// A note shorter than a beat is left to run into the next note (the two
// eighth-note pickups are sung as one gesture); anything a beat or longer gets
// a KEYOFF just before it ends, so the ADSR release is heard between words.
const leadPats = Array.from({ length: BARS }, (_, bar) => P(pattern(ROWS, d => {
    for (const [start, name, oct, len] of MELODY) {
        if (start < bar * ROWS || start >= (bar + 1) * ROWS) continue;
        d[start - bar * ROWS] = row(note(name, oct), I_LEAD);
        const off = start + len - 1;
        if (len >= BEAT && off < (bar + 1) * ROWS) d[off - bar * ROWS] = row(KEYOFF);
    }
})));

// --- voice 1: the "oom" of the waltz - root on the downbeat, then two short
// staccato answers an octave and a fifth up.
const bassPats = CHORDS.map(c => P(pattern(ROWS, d => {
    const r = note(c.root, c.oct);
    d[0] = row(r, I_BASS);            d[3]  = row(KEYOFF);
    d[4] = row(r + 12, I_BASS);       d[6]  = row(KEYOFF);
    d[8] = row(r + 7, I_BASS);        d[10] = row(KEYOFF);
})));

// --- voice 2: the "pah-pah" - a kick on the downbeat, an arpeggio chord stab
// on beats 2 and 3, and a hat to close the bar. The arp wavetable loops, so
// one trigger holds the chord until the next event steals the voice - which is
// exactly how a three-channel machine plays chords and drums at once.
const arpPats = CHORDS.map(c => P(pattern(ROWS, d => {
    const chordNote = note(c.root, c.oct + 1);
    d[0]  = row(note('C', 3), I_KICK);
    d[4]  = row(chordNote, I_ARP, 0x08, c.arp);   // 8xy picks this bar's arp table
    d[8]  = row(chordNote, I_ARP, 0x08, c.arp);
    d[10] = row(note('A', 5), I_HAT);
})));

// A snare on the last bar's second beat, as a turnaround into the repeat.
patterns[arpPats[BARS - 1]].data[4] = row(note('D', 4), I_SNARE);

// Tempo and the filter arm go on the first row that actually plays - the intro
// bar, which is where every pass through the song starts.
patterns[bassPats[0]].data[0].command = 0x0F;
patterns[bassPats[0]].data[0].cmdData = SPEED;
patterns[arpPats[0]].data[0] = row(note('C', 3), I_KICK, 0x0A, FILTER_SWEEP);

// Order-list transpose byte: 0xE0-0xFD, value = 0xF0 + signed semitones
const TRANSPOSE = (semis) => 0xF0 + semis;

// Two passes: once in C, once a fourth higher. Drums use absolute notes in
// their wavetables, so the transpose lifts the music and leaves the kit alone.
const orderLists = [leadPats, bassPats, arpPats].map(pats =>
    [...pats, TRANSPOSE(5), ...pats, TRANSPOSE(0), 0xFF]);

const song = {
    name: 'Happy Birthday',
    author: 'SID Tracker',
    copyright: 'Traditional - arrangement by tools/make-birthday-song.js',
    subtunes: [{ orderLists }],
    patterns,
    instruments,
    tables: { ltable: L, rtable: R },
};

// ---------------------------------------------------------------- output
const out = process.argv.slice(2).find(a => !a.startsWith('--')) || 'sids/happy-birthday.sng';
const bytes = writeSng(song);
writeFileSync(out, bytes);
console.log(`wrote ${out} (${bytes.length} bytes)`);
console.log(`  ${patterns.length} patterns, ${instruments.length} instruments, ` +
    `WTBL ${L[WTBL].length} / PTBL ${L[PTBL].length} / FTBL ${L[FTBL].length} / STBL ${L[STBL].length}`);
